import{_ as i,C as s,o as h,c as d,a2 as a,j as r,E as t}from"./chunks/framework.sc8Z_ZE3.js";const b=JSON.parse('{"title":"What Octryx AI is","description":"","frontmatter":{},"headers":[],"relativePath":"start/overview.md","filePath":"start/overview.md"}'),l={name:"start/overview.md"},c={class:"ox-ladder"};function p(u,e,w,g,f,m){const o=s("Badge"),n=s("Shot");return h(),d("div",null,[e[3]||(e[3]=a('<h1 id="what-octryx-ai-is" tabindex="-1">What Octryx AI is <a class="header-anchor" href="#what-octryx-ai-is" aria-label="Permalink to &quot;What Octryx AI is&quot;">​</a></h1><p>Octryx AI is the layer above your coding agent. You bring Claude Code on your own subscription (Codex support is experimental); Octryx AI brings the <strong>process</strong>, the <strong>checks</strong> and the <strong>record</strong>.</p><ul><li><strong>Process.</strong> A workflow decides the phases of a piece of work, the checks in each phase and who has to approve what. Your coding agent does the work inside that frame, phase by phase.</li><li><strong>Checks.</strong> The platform checks the work, not the agent. For a bug, the new test must fail on the old code and pass after the fix. The repository&#39;s declared tests run without the agent. An independent review reads the change.</li><li><strong>Record.</strong> Every run leaves a record next to its pull request: phases, evidence, decisions, tokens and cost.</li></ul><p>Octryx AI is open source under Apache 2.0 and early: version 0.0.1-alpha. Each page in this wiki shows the real status of what it describes.</p><div class="warning custom-block"><p class="custom-block-title">Alpha: no warranty</p><p>Octryx AI is early and changing: expect rough edges, breaking changes between versions and features that are not finished. Do not run this alpha with production data or expose it to the internet. It is provided &quot;AS IS&quot;, without warranties or conditions of any kind; you use it at your own risk and are responsible for its use, including what its agents do in connected systems. To the extent permitted by applicable law, the authors and contributors are not liable for any damages arising from its use (Apache License 2.0, sections 7 and 8). See <a href="/docs/start/known-limitations">Known limitations</a>.</p></div>',5)),r("div",c,[t(o,{type:"planned",text:"Planned"}),e[0]||(e[0]=r("span",{class:"arrow"},"→",-1)),t(o,{type:"progress",text:"Building"}),e[1]||(e[1]=r("span",{class:"arrow"},"→",-1)),t(o,{type:"built",text:"Built"}),e[2]||(e[2]=r("span",{class:"arrow"},"→",-1)),t(o,{type:"tried",text:"In real runs"})]),e[4]||(e[4]=a('<p>See <a href="/docs/start/status">Status and results</a> for what each stage means and what we measured.</p><h2 id="where-the-work-happens" tabindex="-1">Where the work happens <a class="header-anchor" href="#where-the-work-happens" aria-label="Permalink to &quot;Where the work happens&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>Runs where</th><th>What it does</th></tr></thead><tbody><tr><td>The platform</td><td>Your server, or a local stack on one machine</td><td>Workspaces, workflows, chat, knowledge, rules, connections, the record</td></tr><tr><td><code>octryx-claude</code></td><td>Each developer&#39;s machine</td><td>Starts Claude Code (Codex: experimental) for a run phase, in a clone of the repository, on the person&#39;s own subscription</td></tr><tr><td>Connections</td><td>Your existing tools</td><td>Jira, Confluence, GitHub, GitLab, Bitbucket and more: read work items and pages, push branches, open pull requests</td></tr></tbody></table><p>There is no server checkout: each run works in its own clone on the machine that runs the agent. Job output and transcripts are redacted for secrets on the machine before they are sent. What else leaves the machine is listed under <a href="/docs/install/launcher#what-leaves-the-machine">Launcher and devices</a>.</p><h2 id="a-run-in-five-steps" tabindex="-1">A run in five steps <a class="header-anchor" href="#a-run-in-five-steps" aria-label="Permalink to &quot;A run in five steps&quot;">​</a></h2>',5)),t(n,{src:"/shots/runs.png",alt:"Work › Runs in the Demo Shop: one run waits for a product-owner decision, one is implementing, one has shipped",caption:"Work › Runs: what waits for you, and every run with its step, result and cost."}),e[5]||(e[5]=a('<ol><li><strong>A work item comes in</strong>: a bug or a story from your tracker, or a line in the chat.</li><li><strong>A workflow takes it</strong>, for example &quot;Bug fix with a reproduction test&quot; or &quot;Story / epic delivery&quot;.</li><li><strong>Your coding agent works on your machine</strong>, phase by phase.</li><li><strong>The platform checks</strong>: red before, green after, the declared tests, an independent review.</li><li><strong>You get a pull request and a record.</strong> The <a href="/docs/review-bot/">review bot</a> comments on the pull request like on any other.</li></ol><p>Octryx AI never merges. People decide.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>New here: <a href="/docs/start/first-run">First run</a> and <a href="/docs/concepts/workflows">Workflows and phases</a>.</li><li>Daily work: <a href="/docs/work/chat">Chat</a>, <a href="/docs/work/mobile">Mobile web app</a>, <a href="/docs/work/git">Git and pull requests</a>.</li><li>Set up for a team: <a href="/docs/connections/">Connections</a>, <a href="/docs/knowledge/guide">Knowledge</a>, <a href="/docs/rules/policies">Rules</a>, <a href="/docs/admin/operations">Operations</a>.</li></ul>',4))])}const y=i(l,[["render",p]]);export{b as __pageData,y as default};
